"""Prepared hosted-account UI; network remains outside the isolated report."""
PANEL = """<section class="online-account"><h3>ChatGPT inside Reversium</h3><p id="online-ai-status" role="status">Account integration is being prepared. Awaiting hosted access approval.</p><p>Once enabled, you will connect your own eligible account, review the exact question and selected evidence, and read the answer here. ZIP files stay on your device. Approved question/evidence text will leave your device only when you send it. No connection is available yet.</p><nav><button id="online-connect" disabled>Connect ChatGPT account</button><button id="online-disconnect" disabled>Disconnect and clear answer</button></nav><p>Use the question and evidence selection below, then prepare the account request for review.</p><button id="online-prepare">Prepare account request</button><label for="online-preview">Exact account request (JSON, editable)</label><textarea id="online-preview" rows="8" style="width:100%;box-sizing:border-box"></textarea><label><input type="checkbox" id="online-approve"> I have reviewed this exact request and approve sending it.</label><nav><button id="online-send" disabled>Send approved request</button><button id="online-cancel" disabled>Cancel request</button></nav><div id="online-answer" aria-live="polite"></div><p>Citations can be checked against the selected findings; a valid citation does not prove an explanation is correct. This conversation is not included in report downloads.</p></section>"""
SCRIPT = r"""
(()=>{
if(!document.querySelector('#panel-assistant'))return;
let state='awaiting_approval',pending=new Map(),sequence=0;
const $=s=>document.querySelector(s),preview=$('#online-preview'),consent=$('#online-approve');
function status(message){$('#online-ai-status').textContent=message||({awaiting_approval:'Awaiting hosted access approval. No account is connected.',disconnected:'Not connected. No evidence has been shared.',connecting:'Connecting account… No evidence is shared by sign-in.',connected:'Account connected. Review and approve each request before sending.',sending:'Sending your approved request…'})[state];$('#online-connect').disabled=state!=='disconnected';$('#online-disconnect').disabled=!['connected','sending','connecting'].includes(state);$('#online-send').disabled=state!=='connected'||!consent.checked||!preview.value.trim();$('#online-cancel').disabled=state!=='sending';}
function request(action,extra={}){if(parent===window){status('Account connections work only inside the live application. Saved reports contain no account session.');return}const requestId='ai-'+(++sequence);pending.set(requestId,action);parent.postMessage({type:'reversium-account-ai',requestId,action,...extra},'*');if(action==='connect')state='connecting';if(action==='ask')state='sending';status();}
function invalidate(){consent.checked=false;status()}
window.addEventListener('reversium-selection-changed',invalidate);$('#ai-question').addEventListener('input',invalidate);preview.oninput=invalidate;consent.onchange=()=>status();
$('#online-connect').onclick=()=>request('connect');$('#online-disconnect').onclick=()=>{$('#online-answer').replaceChildren();invalidate();request('disconnect')};$('#online-cancel').onclick=()=>request('cancel');
$('#online-prepare').onclick=()=>{consent.checked=false;try{const report=JSON.parse($('#report-data').textContent),question=$('#ai-question').value.trim(),ids=[...window.reversiumSelectedEvidence||[]];if(!question||!ids.length)throw Error();const packet={question,evidence:ids.map(id=>({id,text:JSON.stringify(report.findings[id])}))};preview.value=JSON.stringify(packet,null,2);status('Review the exact JSON. Only this question and selected evidence would be sent.');}catch{preview.value='';status('Enter a question and select evidence first.')}status($('#online-ai-status').textContent)};
$('#online-send').onclick=()=>{try{const packet=JSON.parse(preview.value);if(!consent.checked)return;consent.checked=false;request('ask',{packet,approved:true})}catch{status('Request is not valid JSON. Review it before sending.')}};
window.addEventListener('message',event=>{const d=event.data;if(event.source!==parent||d?.type!=='reversium-account-ai-result'||!pending.has(d.requestId))return;pending.delete(d.requestId);state=d.state;status(d.error);if(d.answer){const area=$('#online-answer');area.replaceChildren();for(const claim of d.answer.claims){const p=document.createElement('p');p.append(document.createTextNode(claim.text+' '));for(const id of claim.evidence_ids){const a=document.createElement('a');a.href='#finding-'+id;a.textContent='['+id+'] ';a.onclick=e=>{e.preventDefault();revealFinding(a.getAttribute('href'))};p.append(a)}area.append(p)}const h=document.createElement('h4');h.textContent='Unknowns';area.append(h);for(const text of d.answer.unknowns){const p=document.createElement('p');p.textContent=text;area.append(p)}}});
status();request('status');
})();
"""
